import sys
from datetime import date, timedelta, datetime

def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)

def clock(total):
    return f"{total // 60:02d}:{total % 60:02d}"

def main():
    settings = {}
    busy = {}
    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == "busy":
            who, day, start, end = parts[1:]
            busy.setdefault((who, day), []).append((minutes(start), minutes(end)))
        else:
            settings[parts[0]] = parts[1:]
    first = date.fromisoformat(settings["days"][0])
    last = date.fromisoformat(settings["days"][1])
    open_at, close_at = (datetime.combine(day, datetime.min.time()).hour * 60 + minutes(t)
                          for t in settings["hours"])
    need = int(settings["duration"][0])
    buffer = int(settings["buffer"][0]) if "buffer" in settings else 0

    day = first
    while day <= last:
        key = day.isoformat()
        taken = []
        for (who, day_key), intervals in busy.items():
            for start, end in intervals:
                taken.append((start, end))

        slots = []
        cursor = open_at
        for s, e in taken:
            if s - cursor >= need:
                slots.append(f"{clock(cursor)}-{clock(s)}")
            cursor = e
        if close_at - cursor >= need:
            slots.append(f"{clock(cursor)}-{clock(close_at)}")

        free = []
        current_start = open_at
        for s, e in taken:
            if current_start < s - buffer:
                free.append(f"{clock(current_start)}-{clock(s - buffer)}")
            current_start = max(current_start, s + buffer)
        if current_start < close_at:
            free.append(f"{clock(current_start)}-{clock(close_at)}")

        free = [slot for slot in free if (close_at - current_start) >= need]

        print(f"{key} {' '.join(free)} or none" if free else f"{key} none")


if __name__ == "__main__":
    main()
